        w = sum(row.count(WHITE) for row in self.grid)
        return b, w

    def is_full(self):
        return all(cell != EMPTY for row in self.grid for cell in row)

    def game_over(self):
        return self.is_full() or not (self.valid_moves(BLACK) or self.valid_moves(WHITE))
